effect.shader:
vec4 u_xlat0;
bvec2 u_xlatb1;
bvec2 u_xlatb4;
void main()
{
    u_xlat0.xy = acScreenNorm.xy + vec2(-0.5, -0.5);
    u_xlat0.xy = u_xlat0.xy / _ratio.xy;
    u_xlat0.xy = u_xlat0.xy + vec2(0.5, 0.5);
    u_xlatb4.xy = lessThan(u_xlat0.xyxy, vec4(0.0, 0.0, 0.0, 0.0)).xy;
    u_xlatb1.xy = lessThan(vec4(1.0, 1.0, 0.0, 0.0), u_xlat0.xyxx).xy;
    u_xlatb4.x = u_xlatb4.x || u_xlatb1.x;
    u_xlatb4.x = u_xlatb4.y || u_xlatb4.x;
    u_xlatb4.x = u_xlatb1.y || u_xlatb4.x;
    if(u_xlatb4.x){
        fragColor = vec4(0.0, 0.0, 0.0, 0.0);
        return;
    }
    u_xlat0 = texture(inputImg, u_xlat0.xy);
    fragColor = u_xlat0 * vs_COLOR0;
    return;
}
